class Calculation {public static void main(String[] args){var in=new java.util.Scanner(System.in);int n=in.nextInt();var out=new java.util.ArrayList<String>();for(int i=0;i<n;i++){int value=in.nextInt();String s=Long.toString(Math.abs((long)value));if(s.length()==3&&s.charAt(0)!=s.charAt(1)&&s.charAt(0)!=s.charAt(2)&&s.charAt(1)!=s.charAt(2))out.add(Integer.toString(value));}System.out.println(out.isEmpty()?"Подходящих чисел нет":String.join(" ",out));}}
